def place(eid,name,etype,src,loc,note,vs='local_reported'): return {'id':eid,'schema_version':SCHEMA_VERSION,'country_code':'KW','canonical_name':name,'canonical_name_language':'ar','entity_type':etype,'status':'historical','valid_from':None,'valid_to':None,'canonical_source_id':src,'source_locator':loc,'legacy_ids':[],'coordinates':None,'notes':note,'verification_status':vs,'confidence':'medium'}
