 return {'id':record_id('CLM-KW-DEPTH',key),'schema_version':SCHEMA_VERSION,'subject_id':subject,'predicate':predicate,'value':{'type':'json','data':data},'unit':unit,'status':status,'observed_at':observed,'valid_from':None,'valid_to':None,'source_id':source,'second_source_id':None,'source_locator':loc,'second_source_locator':None,'sensitivity':'ordinary','notes':note,'verification_status':vs,'confidence':conf,'classification':cls,'published':published,'lexical_context':None}
