 replace(ROOT/'data/coverage/denominators.jsonl',lambda r:r.get('country_code')=='KW' and r.get('layer')!='country_scope',denoms);replace(ROOT/'data/coverage/coverage.jsonl',lambda r:r.get('country_code')=='KW' and r.get('layer')!='country_scope',covs);replace(ROOT/'data/snapshots/snapshots.jsonl',lambda r:r.get('id','').startswith('SNP-KW-'),[snapshot := {'id':SNAP,'schema_version':SCHEMA_VERSION,'title':'Kuwait production expansion — six governorates, World Heritage scope, and depth cycle 1','captured_at':DATE,'source_id':SRC,'scope':'Six 2021 census governorates, the zero-property UNESCO inscribed scope, seven UNESCO intangible-heritage elements, and the historic quarters of Kuwait City','method':'Offline deterministic import from checksum-bound reconciled official census, UNESCO, heritage, and mirror fixtures.','checksum':'sha256:'+hashlib.sha256(MAN.read_bytes()).hexdigest(),'notes':'Population table uses census-year precision. Address areas and blocks remain unclosed with no denominator; historic quarters and firjan are places, never current administrative units.'}])
