 m['pilot_layers']=[{'layer':'kw_governorate','entity_types':['kw_governorate'],'local_names':['محافظة'],'authority_name':'Central Statistical Bureau / Public Authority for Civil Information','denominator':6,'denominator_id':'DEN-KW-GOVERNORATES-2021','coverage_record_id':'COV-KW-GOVERNORATES-2021','snapshot_date':ASOF,'source_ids':[SRC,'SRC-KW-CSB-CENSUS-METHODOLOGY-2021'],'license':LIC,'scope_status':'closed','notes':'Complete six-governorate census layer.','special_cases':['Not Stated excluded from entity denominator.']},{'layer':'world_heritage_property','entity_types':['cultural_site'],'local_names':['موقع تراث عالمي'],'authority_name':'UNESCO World Heritage Centre','denominator':0,'denominator_id':'DEN-KW-WHC-20260816','coverage_record_id':'COV-KW-WHC-20260816','snapshot_date':DATE,'source_ids':[WHCS],'license':WHCL,'scope_status':'closed','notes':'Zero inscribed properties; not broad cultural absence.','special_cases':['Six tentative-list sites excluded.']},{'layer':'unesco_intangible_heritage','entity_types':['cultural_site'],'local_names':['عنصر تراث غير مادي'],'authority_name':'UNESCO Intangible Cultural Heritage','denominator':7,'denominator_id':None,'coverage_record_id':None,'snapshot_date':DEPTH_DATE,'source_ids':[ICH],'license':'UNESCO ICH pages; factual extraction with attribution','scope_status':'closed','notes':'Seven inscribed elements on which Kuwait appears; shared elements are never exclusive. No coverage record is asserted because the layer itself is the inscription list.','special_cases':['Shared multi-State files carry classification shared.']},{'layer':'historic_city_quarters','entity_types':['quarter','lane'],'local_names':['فريج','سكة','حي قديم'],'authority_name':None,'denominator':None,'denominator_id':None,'coverage_record_id':None,'snapshot_date':DEPTH_DATE,'source_ids':[KUNA,MIRQAB],'license':'Historic narratives from state news agency and local heritage archives; reuse terms not stated','scope_status':'open','notes':'Bounded heritage-attested set of the four historic quarters, twelve firjan, and one sikka; no complete register exists and no percentage is claimed.','special_cases':['Historical places only: located_in relationships, no administrative parent, no population claims.']}]
